function CountOddLowerCaseLetters(txt: string) : int
    requires txt != null
    ensures 0 <= CountOddLowerCaseLetters(txt) <= |txt|
{
    var count := 0;
    var i := 0;
    while i < txt.Length
        invariant 0 <= i <= txt.Length
        invariant count == CountLowerCaseLettersAtOddPositions(txt, i)
    {
        if 'a' <= txt[i] <= 'z' && (i % 2 == 1) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountLowerCaseLettersAtOddPositions(txt: string, upTo: int) : int
    requires txt != null
    requires upTo >= 0 && upTo <= txt.Length
    ensures CountLowerCaseLettersAtOddPositions(txt, upTo) == CountOddLowerCaseLetters(txt[..upTo])
{
    var count := 0;
    var i := 1; // we start checking from the first odd position
    while i < upTo
        invariant 0 <= i <= upTo
        invariant count == CountLowerCaseLettersAtOddPositions(txt, i)
    {
        if 'a' <= txt[i] <= 'z' {
            count := count + 1;
        }
        i := i + 2; // move to the next odd position
    }
    return count;
}

